void testLcd_createEscBtn(lv_obj_t * parent, lv_event_cb_t clickCb, int extra)
{
	lv_obj_t * btnA = lv_btn_create(parent);

	lv_obj_t * labelA = lv_label_create(btnA);
	lv_label_set_text(labelA, "Esc");
	lv_obj_add_event_cb(btnA, clickCb, LV_EVENT_CLICKED, NULL);
	lv_obj_align(btnA, LV_ALIGN_TOP_MID, 0, 0);
	lv_obj_set_style_shadow_width(btnA, 0, 0);
	lv_obj_set_style_shadow_width(labelA, 0, 0);
}


int createLcdTestTop(void)
{
	printf("crtLcdTst A\n");
	lv_obj_t * mainWin = lv_obj_create(lv_scr_act());
	lv_obj_set_size(mainWin, SCREEN_WIDTH, SCREEN_HEIGHT);
	lv_obj_set_style_border_width(mainWin, 0, 0);
	lv_obj_set_style_pad_all(mainWin, 0, 0);
	lv_obj_set_style_bg_color(mainWin, lv_color_white(), 0);

	lv_obj_t * imgA = lv_img_create(mainWin);
	lv_obj_remove_style_all(imgA);
	lv_obj_align(imgA , LV_ALIGN_TOP_LEFT, 0, 0);
	const lv_img_dsc_t * pImgDsc = &g_imgDscYoudao; 
	lv_img_set_src(imgA, pImgDsc);
	lv_obj_set_size(imgA, pImgDsc->header.w, pImgDsc->header.h);
	lv_obj_set_style_shadow_width(imgA, 0, 0);

	//sys_setCurMainWinAndCb(mainWin, );
	g_my_bgWin = mainWin;
	testLcd_createEscBtn(mainWin, _my_esc_btn_click_cb, 0);
	printf("crtLcdTst H\n");
	return 0;
}


